mapper.select:
select MST_FEEINFO.FEE_ID id, MST_FEEINFO.FEE_NAME text from MST_FEEINFO where MST_FEEINFO.APPLY_TYPE in (#{relationProd}, #{relationOther}) and MST_FEEINFO.CHARGE_TYPE = #{chargeType02}
and (MST_FEEINFO.FEE_ID like concat('%', #{search}, '%') or MST_FEEINFO.FEE_NAME like concat('%', #{search}, '%'))
and MST_FEEINFO.FEE_ID = #{initValue}
union all select DISTINCT MST_FEEINFO.FEE_ID id, concat_ws('',MST_FEEINFO.FEE_ID, ':',MST_FEEINFO.FEE_NAME) text from FIN_CASH_INFO,FIN_PRODUCT,MST_FEEINFO,FIN_PRODUCT_ADD ,FIN_CASH_PAY_RULE where MST_FEEINFO.APPLY_TYPE in (#{relationProd}, #{relationOther}) and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID and FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle} and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId} and MST_FEEINFO.CHARGE_TYPE = #{chargeType01} AND (FIN_CASH_INFO.IS_CALC IS NULL OR FIN_CASH_INFO.IS_CALC = #{yes})
and (MST_FEEINFO.FEE_ID like concat('%', #{search}, '%') or MST_FEEINFO.FEE_NAME like concat('%', #{search}, '%'))
and MST_FEEINFO.FEE_ID = #{initValue}
union all select MST_FEEINFO.FEE_ID id, concat_ws('',MST_FEEINFO.FEE_ID,':',MST_FEEINFO.FEE_NAME) text from MST_FEEINFO where MST_FEEINFO.APPLY_TYPE in (#{relationProd}, #{relationOther}) and MST_FEEINFO.FEE_TYPE = #{feeType04} and (select FIN_PRODUCT.PROFIT_TYPE from FIN_PRODUCT_ADD,FIN_PRODUCT where FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_PRODUCT.P_FINPROD_ID IS NULL and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}) = #{profitType02}
and (MST_FEEINFO.FEE_ID like concat('%', #{search}, '%') or MST_FEEINFO.FEE_NAME like concat('%', #{search}, '%'))
and MST_FEEINFO.FEE_ID = #{initValue}

    	select *from (


    				select distinct DATE_FORMAT(max(TRD_PRODUCT_DEAL.MDATE), '%Y-%m-%d')
			    	  from TRD_FIN_PRODUCT_DEAL_TOTAL, TRD_PRODUCT_DEAL, TRD_TRADE_FEE_DETAIL
			    	 where TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = TRD_PRODUCT_DEAL.TOTLE_TRADE_ID     
			    	   and TRD_PRODUCT_DEAL.TRADE_ID = TRD_TRADE_FEE_DETAIL.TRADE_ID
			    	   and TRD_FIN_PRODUCT_DEAL_TOTAL.PORTFOLIO_ID = #{ptlId}
			    	   and TRD_FIN_PRODUCT_DEAL_TOTAL.IS_CANCEL = #{isCancel}
					   and TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_STATUS = #{tradeStatus}
			    	   and TRD_TRADE_FEE_DETAIL.FEE_ID = #{feeId}


			    	 select distinct DATE_FORMAT(max(TRD_PRODUCT_DEAL.MDATE), '%Y-%m-%d')
			    	  from TRD_FIN_PRODUCT_DEAL_TOTAL, TRD_PRODUCT_DEAL, TRD_TRADE_FEE_DETAIL,FIN_CASH_PAY_RULE
			    	 where TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = TRD_PRODUCT_DEAL.TOTLE_TRADE_ID
			    	 	AND TRD_PRODUCT_DEAL.Cash_Id=FIN_CASH_PAY_RULE.Cash_Id

					      	AND    FIN_CASH_PAY_RULE.PAY_CYCLE != #{payCycle}

			    	   and TRD_PRODUCT_DEAL.TRADE_ID = TRD_TRADE_FEE_DETAIL.TRADE_ID
			    	   and TRD_FIN_PRODUCT_DEAL_TOTAL.PORTFOLIO_ID = #{ptlId}
			    	   and TRD_FIN_PRODUCT_DEAL_TOTAL.IS_CANCEL = #{isCancel}
					   and TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_STATUS = #{tradeStatus}
			    	   and TRD_TRADE_FEE_DETAIL.FEE_ID = #{feeId}


    	)

select TDY_ACCUMUL_PAY_FEE from PTL_FEE_POSITION
where PORTFOLIO_ID = #{ptlId}
  and CDATE = STR_TO_DATE(#{cdate}, '%Y-%m-%d') - 1
  and PTL_FEE_TYPE = #{feeType}

SELECT SUM(IFNULL(TDY_UNPAID_INTINCEXP, 0)) FROM (
	select TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE
	where FEE_TYPE = #{feeType}
	  and CDATE = STR_TO_DATE(#{cdate}, '%Y-%m-%d') - 1
	  and FINPROD_ID = #{finprodId}
	  and P_FINPROD_ID IS NULL
	UNION ALL
	select TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE
	where FEE_TYPE = #{feeType}
	  and CDATE = STR_TO_DATE(#{cdate}, '%Y-%m-%d') - 1
	  and FINPROD_ID = #{finprodId}
	  and P_FINPROD_ID IS not NULL
	)

		select FIN_FLOAT_ACCRUAL_SCHE.ACCR_STR_DATE 
		from fin_cash_info ,FIN_FLOAT_ACCRUAL_SCHE  
        where fin_cash_info.finprod_id = #{finprodId}
        and fin_cash_info.cash_type_1 = #{CASH_TYPE_1_03}
        and fin_cash_info.cash_type_2 = #{CASH_TYPE_2_C04}
        and FIN_FLOAT_ACCRUAL_SCHE.CASH_ID = fin_cash_info.cash_id
        and FIN_FLOAT_ACCRUAL_SCHE.ACCR_DATE = STR_TO_DATE(#{cdate}, '%Y-%m-%d')

select FINPROD_ID finprodId,FEE_TYPE feeType,BRANCH branch,'' sFinprodId, CDATE cdate, TDY_POSITION tdyPosition, TDY_FEE_RATE tdyFeeRate, TDY_INTINCEXP_ADD tdyIntincexpAdd from BOK_POSITION_PRDFEE where FEE_TYPE = #{feeType} and CDATE > = str_to_date(#{startDate}, '%Y-%m-%d') and CDATE < str_to_date(#{enddate}, '%Y-%m-%d') and FINPROD_ID = #{finprodId}
and BRANCH = #{branch}
and P_FINPROD_ID IS NULL UNION ALL select FINPROD_ID finprodId,FEE_TYPE feeType,BRANCH branch,'' sFinprodId, CDATE cdate, TDY_POSITION tdyPosition, TDY_FEE_RATE tdyFeeRate, TDY_INTINCEXP_ADD tdyIntincexpAdd from BOK_POSITION_PRDFEE where FEE_TYPE = #{feeType} and CDATE > = str_to_date(#{startDate}, '%Y-%m-%d') and CDATE < str_to_date(#{enddate}, '%Y-%m-%d') and P_FINPROD_ID = #{finprodId}
and BRANCH = #{branch}
UNION ALL select B.FINPROD_ID finprodId ,ptl_FEE_TYPE feeType, 0 branch ,'' sFinprodId , CDATE cdate , IFNULL(TDY_FEE_CAPITAL,0) tdyPosition , IFNULL(TDY_FEE_RATE,0) tdyFeeRate, TDY_ACCUMUL_PAY_FEE tdyIntincexpAdd from PTL_FEE_POSITION A inner join FIN_PRODUCT_ADD B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN FIN_PRODUCT C ON B.FINPROD_ID=C.FINPROD_ID where A.ptl_FEE_TYPE = #{feeType} AND C.PROFIT_TYPE = #{profitType} AND C.P_FINPROD_ID IS NULL and A.CDATE > = str_to_date(#{startDate}, '%Y-%m-%d') and A.CDATE < str_to_date(#{enddate}, '%Y-%m-%d') and B.FINPROD_ID = #{finprodId} UNION ALL SELECT (CASE WHEN BOK_POSITION_PRDFEE.FINPROD_ID = FIN_PRODUCT.FINPROD_MARKET_ID THEN FIN_PRODUCT1.FINPROD_MARKET_ID ELSE BOK_POSITION_PRDFEE.FINPROD_ID END) finprodId,
BOK_POSITION_PRDFEE.Fee_Type feeType, 0 AS branch , (CASE WHEN BOK_POSITION_PRDFEE.P_FINPROD_ID = NULL THEN FIN_PRODUCT1.FINPROD_MARKET_ID ELSE BOK_POSITION_PRDFEE.Finprod_Id END) sFinprodId,
BOK_POSITION_PRDFEE.CDATE cdate, BOK_POSITION_PRDFEE.TDY_POSITION AS tdyPosition, BOK_POSITION_PRDFEE.TDY_FEE_RATE AS tdyFeeRate , IFNULL(BOK_POSITION_PRDFEE.TDY_INTINCEXP_ADD,0) AS tdyIntincexpAdd FROM BOK_POSITION_PRDFEE LEFT JOIN FIN_PRODUCT ON BOK_POSITION_PRDFEE.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT FIN_PRODUCT1 ON BOK_POSITION_PRDFEE.P_FINPROD_ID = FIN_PRODUCT1.FINPROD_ID where BOK_POSITION_PRDFEE.FINPROD_ID = #{finprodId}
AND BOK_POSITION_PRDFEE.FEE_TYPE = #{feeType} AND BOK_POSITION_PRDFEE.P_FINPROD_ID IS NOT NULL and BOK_POSITION_PRDFEE.CDATE > = str_to_date(#{startDate}, '%Y-%m-%d') and BOK_POSITION_PRDFEE.CDATE < str_to_date(#{enddate}, '%Y-%m-%d')

select FIN_PRODUCT_ADD.FINPROD_ID finprodId, BOK_POSITION_PRDFEE.BRANCH branch, '' sFinprodId, SUM(IFNULL(BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP, 0)) actPayAmt from BOK_POSITION_PRDFEE, FIN_PRODUCT_ADD, FIN_PRODUCT where BOK_POSITION_PRDFEE.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}
and BOK_POSITION_PRDFEE.FEE_TYPE = #{feeType}
and BOK_POSITION_PRDFEE.CDATE = STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d')
and BOK_POSITION_PRDFEE.CDATE = STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') -1
and BOK_POSITION_PRDFEE.P_FINPROD_ID is NULL group by FIN_PRODUCT_ADD.FINPROD_ID, BOK_POSITION_PRDFEE.BRANCH union all
select FIN_PRODUCT_ADD.FINPROD_ID finprodId, BOK_POSITION_PRDFEE.BRANCH branch, BOK_POSITION_PRDFEE.FINPROD_ID sFinprodId, SUM(IFNULL(BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP, 0)) actPayAmt from BOK_POSITION_PRDFEE, FIN_PRODUCT_ADD, FIN_PRODUCT,FIN_PRODUCT F1 where BOK_POSITION_PRDFEE.P_FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND F1.P_FINPROD_ID=FIN_PRODUCT_ADD.FINPROD_ID
and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}
and BOK_POSITION_PRDFEE.FEE_TYPE = #{feeType}
and BOK_POSITION_PRDFEE.CDATE = STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d')
and BOK_POSITION_PRDFEE.CDATE = STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') -1
group by FIN_PRODUCT_ADD.FINPROD_ID, BOK_POSITION_PRDFEE.BRANCH,BOK_POSITION_PRDFEE.FINPROD_ID union all
select FIN_PRODUCT_ADD.FINPROD_ID finprodId, 0 branch, '' sFinprodId, SUM(IFNULL(PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE, 0)) actPayAmt from PTL_FEE_POSITION, FIN_PRODUCT_ADD, FIN_PRODUCT where PTL_FEE_POSITION.PORTFOLIO_ID = FIN_PRODUCT_ADD.PORTFOLIO_ID and FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}
and PTL_FEE_POSITION.PTL_FEE_TYPE = #{feeType} and PTL_FEE_POSITION.CDATE = STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') - 1 and FIN_PRODUCT.p_Finprod_Id is null group by FIN_PRODUCT_ADD.FINPROD_ID

	SELECT
		TEMP.finprodMarketId finprodMarketId,
		TEMP.finprodId finprodId,
		TEMP.sFinprodId sFinprodId,
		TEMP.feeId feeId,
		sys_datadict_list.item_value basicBill,
		TEMP.feeName feeName,
		TEMP.feeType feeType,	
		TEMP.calcStartDate calcStartDate,
		TEMP.calcEndDate calcEndDate,	
		TEMP.ccy ccy,
		TEMP.actPayAmt actPayAmt,
		TEMP.payAmt payAmt																		
		FROM(
			SELECT
			FIN_PRODUCT_ADD.PORTFOLIO_ID finprodMarketId
			,FIN_PRODUCT.Finprod_Id finprodId	
			,NULL as sFinprodId
			,MST_FEEINFO.FEE_ID	feeId
			,MST_FEEINFO.BASIC_BILL basicBill
			,MST_FEEINFO.Fee_Name feeName
			,BOK_POSITION_PRDFEE.FEE_TYPE feeType 
			,TRD_PRODUCT_DEAL.MDATE as calcStartDate


			,CASE WHEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE < STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d')
			THEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE
			ELSE STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') END as calcEndDate
			,FIN_CASH_INFO.ccy   
			,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as actPayAmt 
			,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as payAmt                                             
		    FROM                                                                     
		      FIN_CASH_INFO                                                                 
		    INNER JOIN FIN_CASH_PAY_RULE                                                     
		        ON    FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID    

				      	AND    FIN_CASH_PAY_RULE.PAY_CYCLE != #{payCycle}


				      	AND    FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle}

		    INNER JOIN        MST_FEEINFO                                                  
		        ON    FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID                                        
		        AND    MST_FEEINFO.CHARGE_TYPE IN(#{chargeType})                         
		    INNER JOIN        BOK_POSITION_PRDFEE                                                
		        ON    FIN_CASH_INFO.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID                                  
		        AND    FIN_CASH_INFO.BRANCH = BOK_POSITION_PRDFEE.BRANCH                                     
		        and    FIN_CASH_INFO.CASH_TYPE_2 = BOK_POSITION_PRDFEE.FEE_TYPE
		   LEFT JOIN (select FINPROD_ID, BRANCH, FINPROD_TYPE2, mdate
							from (select d.*,
							 rnum
	from (
	/* 子查询必加上rn字段 */
	SELECT result.* FROM (
	SELECT tmp.*,
	@rownum := @rownum + 1 row, /* 虚拟列行标 */
	IF(
	(
	@FINPROD_ID = tmp.FINPROD_ID and
	@BRANCH = tmp.BRANCH
	@FINPROD_TYPE2 = tmp.FINPROD_TYPE2
	),
	@rank := @rank + 1,
	@rank := 1
	) AS rnum, /* 分组虚拟列行标 */
	/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
	@FINPROD_ID := tmp.FINPROD_ID /* 分组条件1 */
	, @BRANCH := tmp.BRANCH /* 分组条件2 */
	, @FINPROD_TYPE2 := tmp.FINPROD_TYPE2 /* 分组条件3 */
	FROM (
	/* 数据源 */
	SELECT bc.*
	FROM TRD_PRODUCT_DEAL bc
	ORDER BY CMDATE desc /* 按实际情况与oracle保持一至的排序 */
	) tmp,
	/* 定义临时变量池 */
	(SELECT @rownum := 0,
	@FINPROD_ID := null,
	@BRANCH = null,
	@FINPROD_TYPE2 = null,
	@rank := 0) a
	) result
	) d


							where d.PS = #{ps}
							AND d.IS_CANCEL = #{isCancel}
							AND d.TRADE_STATUS = #{tradeStatus_01}
							and MDATE < STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') ) t
							where rnum = 1)TRD_PRODUCT_DEAL
                                    on FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID
                                  AND FIN_CASH_INFO.BRANCH = TRD_PRODUCT_DEAL.BRANCH
		        				AND     TRD_PRODUCT_DEAL.FINPROD_TYPE2 = BOK_POSITION_PRDFEE.FEE_TYPE                           
		    LEFT JOIN        FIN_PRODUCT                                                
		        ON    FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID     
		    LEFT JOIN FIN_PRODUCT_ADD
					ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
			LEFT JOIN FIN_FLOAT_COUNTING_RULE ON
				FIN_FLOAT_COUNTING_RULE.CASH_ID = FIN_CASH_INFO.CASH_ID
		    WHERE                                                                    
		      FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}                                         
			AND    FIN_PRODUCT.P_FINPROD_ID is null                                          
			AND    FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}                                      
			AND    FIN_PRODUCT.FINPROD_ID = #{finprodId}                                
			AND    MST_FEEINFO.FEE_ID = #{feeId}  
			AND BOK_POSITION_PRDFEE.CDATE =
	               (SELECT max(B.CDATE)
	                  FROM BOK_POSITION_PRDFEE B
	                 WHERE B.FINPROD_ID =
	                     BOK_POSITION_PRDFEE.FINPROD_ID
	                 AND B.BRANCH =
	                     BOK_POSITION_PRDFEE.BRANCH
	                 AND BOK_POSITION_PRDFEE.FEE_TYPE =
	                     B.FEE_TYPE
	                  AND B.CDATE <STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d'))                                               
		  UNION                                                                     
			SELECT
			FIN_PRODUCT_ADD.PORTFOLIO_ID finprodMarketId
			,FIN_PRODUCT1.FINPROD_MARKET_ID finprodId	
			,FIN_PRODUCT.FINPROD_ID as sFinprodId
			,MST_FEEINFO.FEE_ID	feeId
			,MST_FEEINFO.BASIC_BILL basicBill
			,MST_FEEINFO.Fee_Name feeName
			,BOK_POSITION_PRDFEE.FEE_TYPE feeType 
			,TRD_PRODUCT_DEAL.MDATE as calcStartDate


			,CASE WHEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE < STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d')
			THEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE
			ELSE STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') END as calcEndDate

			,FIN_CASH_INFO.ccy   
			,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as actPayAmt   
			,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as payAmt                                              
		  FROM                                                                       
		    FIN_CASH_INFO                                                                   
		  INNER JOIN FIN_CASH_PAY_RULE                                                       
		      ON    FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID                                    

				      	AND    FIN_CASH_PAY_RULE.PAY_CYCLE != #{payCycle}


				      	AND    FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle}

		  INNER JOIN        MST_FEEINFO                                                    
		      ON    FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID                                          
		      AND    MST_FEEINFO.CHARGE_TYPE IN(#{chargeType})                            
		  INNER JOIN        BOK_POSITION_PRDFEE                                                  
		      ON    FIN_CASH_INFO.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID                                    
		      AND    FIN_CASH_INFO.BRANCH = BOK_POSITION_PRDFEE.BRANCH                                       
		      and    FIN_CASH_INFO.CASH_TYPE_2 = BOK_POSITION_PRDFEE.FEE_TYPE                                      
		  LEFT JOIN (select FINPROD_ID, BRANCH, FINPROD_TYPE2, mdate
						from (select d.*,
						rnum
	from (
	/* 子查询必加上rn字段 */
	SELECT result.* FROM (
	SELECT tmp.*,
	@rownum := @rownum + 1 row, /* 虚拟列行标 */
	IF(
	(
	@FINPROD_ID = tmp.FINPROD_ID and
	@BRANCH = tmp.BRANCH and
	@FINPROD_TYPE2 = tmp.FINPROD_TYPE2
	),
	@rank := @rank + 1,
	@rank := 1
	) AS rnum, /* 分组虚拟列行标 */
	/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
	@FINPROD_ID := tmp.FINPROD_ID /* 分组条件1 */
	, @BRANCH := tmp.BRANCH /* 分组条件2 */
	, @FINPROD_TYPE2 := tmp.FINPROD_TYPE2 /* 分组条件3 */
	FROM (
	/* 数据源 */
	SELECT bc.*
	FROM TRD_PRODUCT_DEAL bc
	ORDER BY CMDATE desc /* 按实际情况与oracle保持一至的排序 */
	) tmp,
	/* 定义临时变量池 */
	(SELECT @rownum := 0,
	@FINPROD_ID := null,
	@BRANCH = null,
	@FINPROD_TYPE2 = null,
	@rank := 0) a
	) result
	) d
						where d.PS = #{ps}
						AND d.IS_CANCEL = #{isCancel}
						AND d.TRADE_STATUS = #{tradeStatus_01}
						and MDATE < STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') ) t
						where rnum = 1)TRD_PRODUCT_DEAL
                                    on FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID
                                  AND FIN_CASH_INFO.BRANCH = TRD_PRODUCT_DEAL.BRANCH
		        				AND     TRD_PRODUCT_DEAL.FINPROD_TYPE2 = BOK_POSITION_PRDFEE.FEE_TYPE
		  LEFT JOIN        FIN_PRODUCT                                                  
		      ON    FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID                                   
		  LEFT JOIN        FIN_PRODUCT   FIN_PRODUCT1                                              
		      ON    BOK_POSITION_PRDFEE.FINPROD_ID = FIN_PRODUCT1.FINPROD_ID   

		  LEFT JOIN FIN_PRODUCT_ADD
					ON FIN_PRODUCT1.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
		  LEFT JOIN FIN_FLOAT_COUNTING_RULE ON
		   			FIN_FLOAT_COUNTING_RULE.CASH_ID = FIN_CASH_INFO.CASH_ID
		  WHERE                                                                      
				FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}                                         
			AND    FIN_PRODUCT.P_FINPROD_ID is not null                                          
			AND    FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}                                      
			AND    FIN_PRODUCT.P_FINPROD_ID = #{finprodId}                                
			AND    MST_FEEINFO.FEE_ID = #{feeId}  
			AND 	BOK_POSITION_PRDFEE.CDATE =
	               (SELECT max(B.CDATE)
	                  FROM BOK_POSITION_PRDFEE B
	                 WHERE B.FINPROD_ID =
	                     BOK_POSITION_PRDFEE.FINPROD_ID
	                 AND B.BRANCH =
	                     BOK_POSITION_PRDFEE.BRANCH
	                 AND BOK_POSITION_PRDFEE.FEE_TYPE =
	                     B.FEE_TYPE

	                 AND B.CDATE <STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d'))


				      	AND FIN_CASH_INFO.CASH_ID = #{cashId}



	    union all

	    select   PTL_PORTFOLIO.PORTFOLIO_ID finprodMarketId
		        ,FIN_PRODUCT_ADD.FINPROD_ID finprodId  
		        ,''  as sFinprodId
		        ,MST_FEEINFO.FEE_ID  feeId
		        ,MST_FEEINFO.BASIC_BILL basicBill
		        ,MST_FEEINFO.Fee_Name feeName
		        ,PTL_FEE_POSITION.PTL_FEE_TYPE feeType 
		        ,IFNULL(TRD_PRODUCT_DEAL.MDATE,PTL_PORTFOLIO.vdate) as calcStartDate


				,CASE WHEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE < STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d')
				THEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE
				ELSE STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') END as calcEndDate

		        ,FIN_CASH_INFO.ccy   
		        ,PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE as actPayAmt   
		        ,PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE as payAmt    
		        from PTL_FEE_POSITION, FIN_PRODUCT_ADD, PTL_PORTFOLIO ,MST_FEEINFO, FIN_CASH_INFO
		        LEFT JOIN (select FINPROD_ID, BRANCH, FINPROD_TYPE2, mdate
							from (select d.*,
							 rnum
	from (
	/* 子查询必加上rn字段 */
	SELECT result.* FROM (
	SELECT tmp.*,
	@rownum := @rownum + 1 row, /* 虚拟列行标 */
	IF(
	(
	@FINPROD_ID = tmp.FINPROD_ID and
	@BRANCH = tmp.BRANCH and
	@FINPROD_TYPE2 = tmp.FINPROD_TYPE2
	),
	@rank := @rank + 1,
	@rank := 1
	) AS rnum, /* 分组虚拟列行标 */
	/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
	@FINPROD_ID := tmp.FINPROD_ID /* 分组条件1 */
	, @BRANCH := tmp.BRANCH /* 分组条件2 */
	, @FINPROD_TYPE2 := tmp.FINPROD_TYPE2 /* 分组条件3 */
	FROM (
	/* 数据源 */
	SELECT bc.*
	FROM TRD_PRODUCT_DEAL bc
	ORDER BY CMDATE desc /* 按实际情况与oracle保持一至的排序 */
	) tmp,
	/* 定义临时变量池 */
	(SELECT @rownum := 0,
	@FINPROD_ID := null,
	@BRANCH = null,
	@FINPROD_TYPE2 = null,
	@rank := 0) a
	) result
	) d
							where d.PS = #{ps}
							AND d.IS_CANCEL = #{isCancel}
							AND d.TRADE_STATUS = #{tradeStatus_01}
							and MDATE < STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') ) t
							where rnum = 1)TRD_PRODUCT_DEAL
			                                    on FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID
			                                  AND FIN_CASH_INFO.BRANCH = TRD_PRODUCT_DEAL.BRANCH  
		                                    and FIN_CASH_INFO.CASH_TYPE_2 = TRD_PRODUCT_DEAL.FINPROD_TYPE2
			LEFT JOIN FIN_FLOAT_COUNTING_RULE ON
					FIN_FLOAT_COUNTING_RULE.CASH_ID = FIN_CASH_INFO.CASH_ID
		    where PTL_FEE_POSITION.PORTFOLIO_ID = FIN_PRODUCT_ADD.PORTFOLIO_ID
		      and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID
		      and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
		      and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} 
		      and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2_C04} 
		      and FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID      
		      and PTL_FEE_POSITION.PTL_FEE_TYPE = FIN_CASH_INFO.CASH_TYPE_2                                    
			  AND MST_FEEINFO.CHARGE_TYPE = #{chargeType}         
		      and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}
		      and PTL_FEE_POSITION.PTL_FEE_TYPE = #{feeType}
		      and PTL_FEE_POSITION.CDATE = STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') - 1
		      and PTL_PORTFOLIO.PROFIT_TYPE = #{profitType}                                                    
		)TEMP left join sys_datadict_list on TEMP.basicBill = sys_datadict_list.item_code and dict_code = 'BILL_BASE_FEE_KIND'


    select sum(PTPD.THEORY_AMT)-sum(TTFD.FEE_AMT) from 
    PA_TRD_PRODUCT_DEAL PTPD ,TRD_TRADE_FEE_DETAIL TTFD,TRD_PRODUCT_DEAL TPD,FIN_PRODUCT_ADD FPA
		WHERE TTFD.TRADE_ID = PTPD.TRADE_ID
		AND TPD.TRADE_ID = PTPD.TRADE_ID
		AND FPA.FINPROD_ID = TPD.FINPROD_ID
		AND TPD.FINPROD_ID = #{finprodId}
	    AND TPD.IS_CANCEL = #{noFlag}
		AND TPD.TRADE_STATUS = #{tradeStatus}

	  	AND FPA.PORTFOLIO_ID = #{ptlId}


		AND TTFD.FEE_ID = #{feeId}


		AND TPD.TRADE_DATE <= STR_TO_DATE(#{payDate},'%Y-%m-%d')

		AND TPD.IS_CLEAN = #{isClean}

  select IFNULL(sum(IFNULL(fee_amt,0)),0) from trd_trade_fee_detail where fee_type=#{feeType1} and trade_id in(
select deal.trade_id from trd_product_deal deal,trd_product_deal_add add1 ,fin_product prod  where prod.finprod_type2 in('F01','F02','F03','F04','F05') and is_cancel='N'
and add1.trade_id=deal.trade_id and add1.portfolio_id=#{ptlId}  and deal.trade_date <= STR_TO_DATE(#{cdate}, '%Y-%m-%d') and deal.finprod_id=prod.finprod_id and prod.REGIST_ORG=#{org}
)

  select IFNULL(sum(IFNULL(trade_amt,0)),0) from  trd_product_deal deal,trd_product_deal_add add1 ,
mst_feeinfo fee,fin_product prod,TRD_TRADE_FEE_DETAIL feed
 where  
 deal.finprod_id=prod.finprod_id 
  and deal.TRADE_ID = feed.TRADE_ID
  and feed.FEE_ID = fee.FEE_ID
  and fee.fee_type=#{feeType} 
  and  deal.trade_id=add1.trade_id
 and add1.portfolio_id=#{ptlId} 

 and deal.IS_CANCEL =#{isCancel_NO}


 	and  deal.REGIST_ORG=#{org} 

 and deal.trade_date = STR_TO_DATE(#{cdate}, '%Y-%m-%d')

select count(*)
from FIN_CASH_INFO,FIN_PRODUCT,MST_FEEINFO,FIN_PRODUCT_ADD ,FIN_CASH_PAY_RULE
where MST_FEEINFO.APPLY_TYPE in (#{relationProd}, #{relationOther})
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID
and FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
and FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID
and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
and FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle}
and CASE MST_FEEINFO.FEE_TYPE WHEN #{feeType_03, jdbcType = VARCHAR} THEN 0 WHEN #{feeType_04, jdbcType = VARCHAR} THEN 0 WHEN #{feeType_12, jdbcType = VARCHAR} THEN 0 ELSE 1 END = 1

	and FIN_CASH_INFO.FINPROD_ID = #{finprodId}



	and (FIN_PRODUCT_ADD.PORTFOLIO_ID in


			null) OR  FIN_PRODUCT_ADD.PORTFOLIO_ID IN (

		#{item}
	)

and MST_FEEINFO.CHARGE_TYPE = #{chargeType01}

	and MST_FEEINFO.FEE_ID = #{initValue}

and not exists (select 1 from TRD_PRODUCT_DEAL where FIN_CASH_INFO.CASH_ID = TRD_PRODUCT_DEAL.CASH_ID
and TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag}
and TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatus}

	and FIN_CASH_INFO.FINPROD_ID = #{finprodId}
)

   		SELECT IFNULL(TDY_ACCUMUL_PAY_FEE,0)
   		FROM PTL_FEE_POSITION
   		WHERE PTL_FEE_TYPE = #{feeType1}
			AND CDATE = STR_TO_DATE(#{cdate}, '%Y-%m-%d')-1
			AND PORTFOLIO_ID = #{ptlId}

				AND PTL_FEE_PLACE = #{org}

