SELECT '${effectStatus}' effectStatus ,PTL_TRADE.PORTFOLIO_ID ptlId ,FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId ,FIN_PRODUCT.FINPROD_ID finprodId ,null saleDepartment ,(CASE WHEN MST_FEEINFO.FEE_ID = NULL THEN MST_FEEINFO1.FEE_ID ELSE MST_FEEINFO.FEE_ID END)as feeId
,(CASE WHEN MST_FEEINFO.FEE_NAME = NULL THEN MST_FEEINFO1.FEE_NAME ELSE MST_FEEINFO.FEE_NAME END) as feeName
,TRD_TRADE_FEE_DETAIL.FEE_TYPE feeType
/*新增费用类型检索 guyunfei 20190923 start*/ ,(CASE WHEN MST_FEEINFO.FEE_TYPE = NULL THEN MST_FEEINFO1.FEE_TYPE ELSEMST_FEEINFO.FEE_TYPE END) as feeType1
/*新增费用类型检索 guyunfei 20190923 end*/ ,MST_FEEINFO.BASIS basis ,TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE as VDATE ,TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE as MDATE ,TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE as payDate ,TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_AMT as feeAmt ,TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID tradeId ,FIN_PRODUCT.FINPROD_ABBR finprodAbbr ,STL_PAY_ORDERS.My_Acct_No as manageAcctount ,STL_PAY_ORDERS.COUNTER_ACCT_NO as feeAccount ,STL_PAY_ORDERS.CCY as CCY ,TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE positionStartDate ,TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE positionEndDate ,TRD_TRADE_FEE_DETAIL.is_prepaid isPerpaid
,FIN_CASH_INFO.CASH_ID cashId
FROM TRD_FIN_PRODUCT_DEAL_TOTAL INNER JOIN PTL_TRADE ON TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID= PTL_TRADE.BUSI_NO LEFT JOIN STL_PAY_ORDERS ON TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = STL_PAY_ORDERS.TRADE_ID LEFT JOIN FIN_PRODUCT ON TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_CASH_INFO ON FIN_CASH_INFO.CASH_ID = TRD_FIN_PRODUCT_DEAL_TOTAL.CASH_ID AND FIN_CASH_INFO.CASH_TYPE_1 =#{cashType1} LEFT JOIN MST_FEEINFO ON FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID LEFT JOIN TRD_TRADE_FEE_DETAIL ON TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = TRD_TRADE_FEE_DETAIL.TRADE_ID LEFT JOIN MST_FEEINFO MST_FEEINFO1 ON TRD_TRADE_FEE_DETAIL.FEE_ID = MST_FEEINFO1.FEE_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE 1=1 AND TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_STATUS=#{tradeStatus} AND TRD_FIN_PRODUCT_DEAL_TOTAL.IS_CANCEL=#{noFlag} AND TRD_FIN_PRODUCT_DEAL_TOTAL.BUSI_TYPE=#{businessType}
and FIN_CASH_INFO.CASH_ID = #{cashId}
and TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE = str_to_date(#{mdate}, '%Y-%m-%d')
and STL_PAY_ORDERS.COUNTER_ACCT_NO in
#{item}
and FIN_PRODUCT.CCY in
#{item}
and PTL_TRADE.PORTFOLIO_ID in
#{item}
and FIN_PRODUCT.FINPROD_ID in
#{item}
and IFNULL(MST_FEEINFO.FEE_ID,MST_FEEINFO1.FEE_ID) = #{feeId}
and TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE >= str_to_date(#{payDateStart}, '%Y-%m-%d')
and TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE <= str_to_date(#{payDateEnd}, '%Y-%m-%d')
/*新增费用类型检索 guyunfei 20190923 start*/
and CASE MST_FEEINFO.FEE_TYPE WHEN NULL THEN MST_FEEINFO1.FEE_TYPE ELSE MST_FEEINFO.FEE_TYPE END = #{feeType}
/*新增费用类型检索 guyunfei 20190923 end*/ /*用户查看组合权限 jyl 20191225 start*/
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
/*用户查看组合权限 jyl 20191225 end*/
